export function createOptimisticStore(initialState) {
  let base = initialState;
  let visibleState = initialState;
  let pending = new Map();
  const subscriptions = new Set();

  function notify() {
    // Snapshot subscriptions so removals cannot disrupt iteration.
    const snapshot = Array.from(subscriptions);
    for (const { listener } of snapshot) {
      try {
        listener();
      } catch {
        // A failing listener must not prevent other notifications.
      }
    }
  }

  function computeVisible(baseState, changes) {
    let state = baseState;
    for (const update of changes.values()) {
      state = update(state);
    }
    return state;
  }

  return {
    getState() {
      return visibleState;
    },

    apply(id, update) {
      if (pending.has(id)) {
        throw new Error("A change with this id is already pending.");
      }

      const nextVisibleState = update(visibleState);
      pending.set(id, update);
      visibleState = nextVisibleState;
      notify();
    },

    confirm(id) {
      if (!pending.has(id)) {
        return false;
      }

      const update = pending.get(id);
      const nextPending = new Map(pending);
      nextPending.delete(id);

      const nextBase = update(base);
      const nextVisibleState = computeVisible(nextBase, nextPending);

      base = nextBase;
      pending = nextPending;
      visibleState = nextVisibleState;
      notify();
      return true;
    },

    rollback(id) {
      if (!pending.has(id)) {
        return false;
      }

      const nextPending = new Map(pending);
      nextPending.delete(id);
      const nextVisibleState = computeVisible(base, nextPending);

      pending = nextPending;
      visibleState = nextVisibleState;
      notify();
      return true;
    },

    subscribe(listener) {
      // Each subscription is independent, even for the same listener.
      const subscription = { listener };
      subscriptions.add(subscription);

      return () => {
        subscriptions.delete(subscription);
      };
    },
  };
}
